async function main() {
  await mongoose.connect(MONGODB_URI);
  try {
    const existing = await InteractiveCourse.findOne({ slug: COURSE.slug });
    if (existing) {
      Object.assign(existing, COURSE);
      await existing.save();
      console.log(`✓ CR-610 UPDATED via .save()`);
    } else {
      await InteractiveCourse.create(COURSE);
      console.log(`✓ CR-610 CREATED via .create()`);
    }
    const final = await InteractiveCourse.findOne({ slug: COURSE.slug });
    console.log(`  sections: ${final.sections.length}`);
    console.log(`  contentBlocks: ${final.totalContentBlocks}`);
    console.log(`  wordCount (pre-save hook): ${final.wordCount}`);
    console.log(`  ceHours: ${final.ceHours}`);
    console.log(`  ACEP floor (3 × 6000): 18000`);
    console.log(`  ${final.wordCount >= 18000 ? '✓ PASSES ACEP floor' : '✗ BELOW ACEP floor'}`);
  } finally {
    await mongoose.disconnect();
  }
}

main().catch(err => { console.error(err); process.exit(1); });
